export default function TaskInterface({task, act}) {
  const t = task || {};
  const m = t.merchant || {};
  const intent = t.intent || {};
  const [pickedMethod, setPickedMethod] = React.useState(null);
  const [pickedReason, setPickedReason] = React.useState(null);
  const overview = !task || t.status === 'not_started';
  const busy = !!t.progress || ['working','created','submitting'].includes(t.status);
  const locked = overview || busy || !!t.receipt;
  const list = value => Array.isArray(value) ? value : [];
  const text = value => value == null ? 'Unknown' : typeof value === 'object' ? JSON.stringify(value) : String(value);
  const money = value => {
    if (typeof value !== 'number' || !m.currency) return 'Unknown';
    try { return new Intl.NumberFormat('en-US', {style:'currency', currency:m.currency}).format(value / 100); }
    catch (_) { return value / 100 + ' ' + m.currency; }
  };
  const methods = list(m.methods).filter(x => ['print_label','qr_dropoff'].includes(x.value));
  const reasons = list(m.reasons).filter(x => x.value);
  const methodLabel = value => (methods.find(x => x.value === value) || {}).label || ({print_label:'Print a shipping label',qr_dropoff:'Printer-free QR drop-off'}[value]) || text(value);
  const destinationLabel = value => (list(m.destinations).find(x => x.value === value) || {}).label || ({original_payment:'Original payment method',store_credit:'Store credit'}[value]) || text(value);
  const requestedDestination = intent.refundDestination || 'original_payment';
  const method = pickedMethod || intent.method || m.method || '';
  const reason = pickedReason === null ? (t.reason || '') : pickedReason;
  const checks = list(t.checks);
  const selected = Array.isArray(m.selectedLines) ? m.selectedLines : null;
  const selectedIds = (selected || []).map(x => typeof x === 'object' ? x.id : x);
  const lines = list(m.lines);
  const selectionConflict = selected && lines.some(x => {
    const nameText = (text(x.name) + ' ' + text(x.id)).toLowerCase();
    return (nameText.includes('jacket') && selectedIds.includes(x.id)) || (nameText.includes('red') && nameText.includes('shoe') && !selectedIds.includes(x.id));
  });
  const destinationConflict = m.refundDestination != null && m.refundDestination !== requestedDestination;
  const methodConflict = !!method && !!m.method && method !== m.method;
  const reasonConflict = !!reason && m.reason != null && reason !== m.reason;
  const failedChecks = checks.filter(x => ['failed','fail','mismatch','conflict','error'].includes(x.status));
  const conflict = destinationConflict || methodConflict || reasonConflict || selectionConflict || failedChecks.length > 0;
  const discovery = t.discovery || {};
  const screens = list(discovery.screens);
  const flows = list(discovery.flows);
  const statusText = t.receipt ? 'A receipt is available from the host. See the separately verified result below.' : busy ? 'Working. Choices are temporarily locked.' : overview ? 'Overview only. No return has been submitted.' : conflict ? 'Source conflict. Review the requested and observed values.' : 'Review current source terms, then validate. Validation is not submission.';
  function chooseMethod(value) { setPickedMethod(value); act('choice', {method:value}); }
  function chooseReason(value) { setPickedReason(value); act('choice', {reason:value}); }
  return <main className="generated-root">
    <header className="generated-header">
      <p className="generated-eyebrow">Merchant sandbox · Synthetic records only</p>
      <h1>{overview ? 'Explore this return' : 'Review your return'}</h1>
      <p className="generated-lead">Return the red shoes. Keep the jacket. Refund original payment.</p>
    </header>
    <div className="generated-status" role="status" aria-live="polite">{statusText}</div>
    {t.error && <section className="generated-warning" role="alert"><h2>Unable to continue</h2><p>{text(t.error.message || t.error)}</p></section>}
    {overview ? <>
      <section className="generated-panel">
        <h2>What was reached</h2>
        {screens.length ? <ul className="generated-list">{screens.map((s,i) => <li key={s.id || i}><strong>{s.name || 'Observed screen'}</strong><p>{s.reachedState || s.stateLabel || 'Screen observed; completion not verified.'}</p></li>)}</ul> : <p>Returns | Merchant sandbox — return choices and draft review observed.</p>}
        {flows.length > 0 && <div className="generated-grid">{flows.map((f,i) => <section className="generated-mini" key={f.id || i}><h3>{f.name || f.label || 'Observed flow'}</h3><p>{text(f.reachedState || f.stateLabel || f.status || 'Reached state not supplied')}</p><p className="generated-muted">Informational discovery; no execution from this card.</p></section>)}</div>}
        <p className="generated-muted">The initial read-only exploration blocked draft writes. Item and reason changes were not fully explored in that run. Later sandbox branches reached the draft states below, not a submitted or independently verified return.</p>
      </section>
      <section className="generated-panel">
        <h2>Two observed method paths</h2>
        <div className="generated-grid">
          <section className="generated-mini"><p className="generated-tag">Reached: saved draft review</p><h3>Print a shipping label</h3><p>Only the red shoes were selected; the jacket was kept. Original payment was selected.</p><p>Print and attach the label, then drop off the parcel.</p></section>
          <section className="generated-mini"><p className="generated-tag">Reached: draft review with conflict</p><h3>Printer-free QR drop-off</h3><p>Only the red shoes were selected; the jacket was kept. Changing the method changed the source destination to store credit.</p><p>A method fee was observed. Review the current fee and restore original payment before approval.</p></section>
        </div>
        <p className="generated-note">Changing the return method can change the refund destination. Current task values, not these historical observations, determine your terms.</p>
      </section>
      <section className="generated-panel"><h2>Supported task</h2><p>Return only the red shoes, keep the jacket, and preserve original payment.</p><p>Use the host’s “Start this task” control to begin. Starting is not approval to submit.</p></section>
    </> : <>
      <div className="generated-layout">
        <div>
          <section className="generated-panel"><p className="generated-eyebrow">01 · Items</p><h2>Return shoes · Keep jacket</h2><p className="generated-muted">These are fixed instructions, not editable item choices.</p>
            {lines.length ? <ul className="generated-list">{lines.map((line,i) => <li key={line.id || i}><strong>{line.name || 'Unnamed item'}</strong>{line.variant && <p>{text(line.variant)}</p>}<p className="generated-muted">Source: {selected === null ? 'selection unknown' : selectedIds.includes(line.id) ? 'selected for return' : 'not selected for return'}</p></li>)}</ul> : <p>Source items: Unknown</p>}
            <p><strong>Your instruction:</strong> Return only red shoes. Keep jacket.</p>
          </section>
          <section className="generated-panel"><p className="generated-eyebrow">02 · Your choices</p><h2>How to handle the return</h2>
            <label className="generated-label" htmlFor="generated-reason">Return reason</label>
            <select id="generated-reason" value={reason} disabled={locked || !reasons.length} onChange={e => chooseReason(e.target.value)}>
              <option value="">Choose a reason</option>
              {reason && !reasons.some(x => x.value === reason) && <option value={reason}>{text(reason)}</option>}
              {reasons.map(x => <option key={x.value} value={x.value}>{x.label}</option>)}
            </select>
            {!reasons.length && <p className="generated-muted">Available reasons are unknown.</p>}
            <label className="generated-label" htmlFor="generated-method">Return method</label>
            <select id="generated-method" value={method} disabled={locked || !methods.length} aria-describedby="generated-method-note" onChange={e => chooseMethod(e.target.value)}>
              <option value="">Choose a method</option>
              {method && !methods.some(x => x.value === method) && <option value={method}>{methodLabel(method)}</option>}
              {methods.map(x => <option key={x.value} value={x.value}>{x.label}</option>)}
            </select>
            <p id="generated-method-note" className="generated-note">Changing the method may change the source refund destination. Your original-payment preference stays unchanged; validate the resulting terms.</p>
            {(methods.find(x => x.value === method) || {}).detail && <p>{text(methods.find(x => x.value === method).detail)}</p>}
            {intent.noPrinter && <p className="generated-note">Your preference: no printer.</p>}
            <p><strong>Requested refund destination</strong><br />{destinationLabel(requestedDestination)}</p>
          </section>
        </div>
        <section className="generated-panel generated-review"><p className="generated-eyebrow">03 · Source review</p><h2>Current observed terms</h2><p className="generated-muted">Source values are separate from your requested choices.</p>
          <dl className="generated-terms">
            <div><dt>Return method</dt><dd>{methodLabel(m.method)}</dd></div>
            <div><dt>Method fee / deduction</dt><dd>{money(m.deductionCents)}</dd></div>
            <div><dt>Refund destination</dt><dd>{destinationLabel(m.refundDestination)}</dd></div>
            <div className="generated-total"><dt>Expected refund</dt><dd>{money(m.expectedRefundCents)}</dd></div>
          </dl>
          {(m.deductionCents == null || m.expectedRefundCents == null || !m.currency || !m.refundDestination || !m.method || selected === null) && <p className="generated-note">Some source terms are unknown. Validate to inspect them; unknown terms must be resolved before approval.</p>}
          <p>Validation checks the source. Exact approval, submission, and separately verified confirmation are handled by the host.</p>
          <button className="generated-primary" disabled={locked} onClick={() => act('check', {repair:false})}>Validate current terms</button>
        </section>
      </div>
      {conflict && <section className="generated-warning"><h2>Your choices and source do not match</h2>
        {destinationConflict && <p><strong>Refund destination</strong><br />Requested: {destinationLabel(requestedDestination)}<br />Observed: {destinationLabel(m.refundDestination)}</p>}
        {methodConflict && <p><strong>Return method</strong><br />Requested: {methodLabel(method)}<br />Observed: {methodLabel(m.method)}</p>}
        {reasonConflict && <p><strong>Return reason</strong><br />Requested: {text(reason)}<br />Observed: {text(m.reason)}</p>}
        {selectionConflict && <p>Requested: return only red shoes; keep jacket.<br />Observed selected items: {selectedIds.map(id => (lines.find(x => x.id === id) || {}).name || text(id)).join(', ') || 'None'}</p>}
        <p>Restore your choices, then review the refreshed source terms. This does not approve a return.</p>
        <button disabled={locked} onClick={() => act('check', {repair:true})}>Restore my choices</button>
      </section>}
      {checks.length > 0 && <section className="generated-panel"><h2>Validation details</h2><ul className="generated-list">{checks.map((c,i) => <li key={i}><strong>{c.label || 'Source check'}</strong><span className="generated-check">{text(c.status)}</span><p>Expected: {text(c.expected)}<br />Observed: {text(c.observed)}</p></li>)}</ul></section>}
    </>}
    <footer className="generated-footer">Sandbox only. No production access. A saved draft is not a completed return.</footer>
  </main>;
}
